<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\CarrierOnboarding;use App\Security\Csrf;use App\Support\Url;Auth::requireLogin();$uid=(int)Auth::user()['id'];if(!CarrierOnboarding::mayOnboard($uid)){http_response_code(403);exit('A requested Truck Owner role is required.');}if(CarrierOnboarding::current($uid)){header('Location: '.Url::to('carrier/profile.php'));exit;}$errors=[];$values=$_POST?:['owner_type'=>'individual','registration_country'=>'TZ'];if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))$errors[]='Invalid form token.';else try{CarrierOnboarding::create($uid,$_POST);header('Location: '.Url::to('carrier/profile.php?created=1'));exit;}catch(RuntimeException$e){$errors[]=$e->getMessage();}catch(Throwable$e){@file_put_contents(BASE_PATH.'/storage/logs/phase6a.log','['.date('c').'] '.$e->getMessage().PHP_EOL,FILE_APPEND|LOCK_EX);$errors[]='Carrier onboarding could not be submitted. Check the local error log.';}}$pageTitle='Carrier Onboarding';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1>Carrier onboarding</h1><p>Submit an individual or company carrier profile for McCollins Operations verification.</p></div><span class="badge">Phase 6A</span></div><div class="notice">Enter licence, TIN, and insurance references only. Document file uploads are deferred to Phase 10.</div><?php foreach($errors as$e):?><div class="error"><?=h($e)?></div><?php endforeach;?><form method="post" class="card"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><?php require BASE_PATH.'/app/Views/carrier/onboarding-form.php';?><div class="actions"><button class="button">Submit for verification</button></div></form><?php require BASE_PATH.'/app/Views/layout/footer.php';
